24: /** Resolves the shot budget: hole data wins, then match settings, then par + default. */
25: export function resolveMaxShotsDetailed(hole: HoleShotBudget, settings?: Pick<MatchSettings, 'strokeLimitPerHole'>): MaxShotsResolution {
26:   if (hole.maxShots !== undefined) {
27:     if (!isPositiveInteger(hole.maxShots)) throw new Error(`Hole ${hole.id}: maxShots must be a positive integer`);
