77: export function rolledVelocity(velocity: Vec3, deceleration: number, dt: number): Vec3 | null {
78:   if (Math.abs(velocity.y) > AIRBORNE_SPEED) return null;
79:   const horizontal = Math.hypot(velocity.x, velocity.z);
80:   if (horizontal <= 1e-4) return null;
81:   const factor = Math.max(0, horizontal - deceleration * dt) / horizontal;
82:   return { x: velocity.x * factor, y: velocity.y, z: velocity.z * factor };
83: }
